import FreeCAD
doc = FreeCAD.open('/home/user/Precondition_Unnamed.FCStd')

# Examine all sketches more carefully
for sk_name in ['Sketch', 'Sketch001', 'Sketch002', 'Sketch003']:
    sk = doc.getObject(sk_name)
    print(f'=== {sk_name} ===')

    # Find all circles
    circles = []
    for i, geom in enumerate(sk.Geometry):
        if hasattr(geom, 'Radius'):
            circles.append((i, geom.Radius, getattr(geom, 'Center', None)))

    print(f'Circles found: {len(circles)}')
    for idx, radius, center in circles:
        print(f'  Index {idx}: Radius={radius}', end='')
        if center:
            print(f' Center={center}')
        else:
            print()
    print()
""}

